if (pos < 3260) {
  const arrowsEq = () => { const a=sdk.getState().equipment.find(e=>/arrow/i.test(e.name)); return a?a.count:0; };
  const startXp = sdk.getSkillXp('Ranged'); const t0=Date.now(); const END=t0+28000;
  while (Date.now()<END) {
    if (arrowsEq()===0){ if(sdk.findInventoryItem(/bronze arrow/i)) await bot.equipItem(/bronze arrow/i); else break; }
    const st=sdk.getState();
    if(!(st.combat?.inCombat)) await bot.attackNpc(/^(Man|Woman)$/i);
    await sdk.waitForTicks(1);
  }
  const gained=sdk.getSkillXp('Ranged')-startXp; const secs=(Date.now()-t0)/1000;
  res={ gained, secs, rawPerMin: Math.round(gained/secs*60), arrowsLeft: arrowsEq() };
}
return { pos: sdk.getState().player.worldX+","+sdk.getState().player.worldZ, res };

