const start = sdk.getSkillXp('Fishing');
const t0 = Date.now();
let drops=0;
while (Date.now() - t0 < 20000) {
  const p = sdk.getState().player;
  // if idle (not fishing animation), re-cast net
  if (p.animId === -1) {
    await bot.interactNpc(/fishing spot/i, 'Net');
  }
  // drop caught shrimps/anchovies to keep inventory free
  const fish = sdk.getInventory().filter(i=>/shrimp|anchov/i.test(i.name) && i.slot!==3);
  for (const f of fish){ await sdk.sendDropItem(f.slot); drops++; }
  await sdk.waitForTicks(1);
}
const end = sdk.getSkillXp('Fishing');
return { gained: end-start, seconds:(Date.now()-t0)/1000, drops, level: sdk.getSkill('Fishing').level };

import { connectBot } from "/app/sdk/index.ts";

const main = async () => {
  // @ts-ignore
  const { bot, sdk } = await (globalThis as any).__getBot?.() ?? {};
};

const start = sdk.getSkillXp('Fishing');
const t0 = Date.now();
let catches=0;
while (Date.now() - t0 < 270000) {
  await bot.dismissBlockingUI();
  const p = sdk.getState().player;
  if (p.animId === -1) {
    await bot.interactNpc(/fishing spot/i, 'Net');
  }
  // drop caught fish to keep fishing continuously
  const fish = sdk.getInventory().filter(i=>/shrimp|anchov|sardine|herring/i.test(i.name) && i.slot!==3);
  for (const f of fish){ await sdk.sendDropItem(f.slot); catches++; }
  await sdk.waitForTicks(1);
}
const end = sdk.getSkillXp('Fishing');
const sec=(Date.now()-t0)/1000;
return { gained: end-start, seconds:sec, ratePerMin: Math.round((end-start)/sec*60), catches, level: sdk.getSkill('Fishing').level };

// diagnostic: click net once, watch behavior without re-clicking
const spot = sdk.findNearbyNpc(/fishing spot/i);
const startXp = sdk.getSkillXp('Fishing');
await sdk.sendInteractNpc(spot.index, 1);
const log=[];
for (let i=0;i<16;i++){
