await bot.dismissBlockingUI();
const spot = ()=>sdk.findNearbyNpc(/fishing spot/i);
// Strategy A: re-click as soon as a catch registers (xp increases)
let startXp = sdk.getSkillXp('Fishing');
let last = startXp;
const t0=Date.now();
let clicks=0, catches=0;
await sdk.sendInteractNpc(spot().index,1); clicks++;
while(Date.now()-t0<15000){
  await sdk.waitForTicks(1);
  const xp=sdk.getSkillXp('Fishing');
  if(xp>last){ catches++; last=xp; await sdk.sendInteractNpc(spot().index,1); clicks++; }
  else if(sdk.getState().player.animId===-1){ await sdk.sendInteractNpc(spot().index,1); clicks++; }
  // keep inv clear
  const fish=sdk.getInventory().filter(i=>/raw (shrimp|anchov)/i.test(i.name));
  for(const f of fish) await sdk.sendDropItem(f.slot);
}
const g=sdk.getSkillXp('Fishing')-startXp;
return {strategy:'reclick-on-catch', gained:g, ratePerMin:Math.round(g/15*60), clicks, catches};

